if "const TEMPO_K = 1/CAM_BASE_Z;" not in open("src/10_core.js", encoding="utf-8").read():
    if os.path.exists("src/72_target.js"):
        sys.exit("v210 ist schon eingespielt.")
    sys.exit("Abbruch: erst v209 einspielen.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
